INSERT INTO `exercise_prescriptions` VALUES (1,1,'Pelvic Tilt','Lie on back with knees bent, feet flat. Gently tilt pelvis posteriorly, flattening lower back against the floor. Hold 5 seconds, release.','stabilization','3','10','2 times/day','2 weeks','Avoid if pain increases',NULL,'2026-07-04 05:30:09','2026-07-04 05:30:09',0,NULL,NULL),(2,1,'Cat-Camel Stretch','Position on hands and knees. Alternate between arching spine upward (cat) and allowing it to sag (camel).','mobilization','2','10','2 times/day','2 weeks',NULL,NULL,'2026-07-04 05:30:09','2026-07-04 05:30:09',0,NULL,NULL),(3,1,'Hamstring Stretch (Supine)','Lie on back, use a towel around the foot to gently pull the straight leg upward until a stretch is felt in the hamstring.','stretching','3','15','2 times/day','4 weeks',NULL,NULL,'2026-07-04 05:30:09','2026-07-04 05:30:09',0,NULL,NULL),(4,1,'Deep Neck Flexor Activation','Lie on back, gently nod the chin without lifting the head. Hold for 10 seconds.','postural','3','10','1 time/day','4 weeks',NULL,NULL,'2026-07-04 05:30:09','2026-07-04 05:30:09',0,NULL,NULL),(5,2,'Quadriceps Setting (Static)','Sit with leg extended. Tighten quadriceps muscle, pushing knee down into the surface. Hold 10 seconds.','strengthening','3','15','3 times/day','2 weeks',NULL,NULL,'2026-07-04 05:30:09','2026-07-04 05:30:09',0,NULL,NULL),(6,2,'Straight Leg Raise (SLR)','Lie on back, one knee bent. Keeping the other leg straight, lift to height of opposite knee. Hold 5 seconds.','strengthening','3','10','3 times/day','4 weeks',NULL,NULL,'2026-07-04 05:30:09','2026-07-04 05:30:09',0,NULL,NULL),(7,2,'Step Up (Low Platform)','Step up onto a low (4 inch) platform leading with the affected leg. Control the descent.','stabilization','3','10','1 time/day','4 weeks',NULL,NULL,'2026-07-04 05:30:09','2026-07-04 05:30:09',0,NULL,NULL),(8,2,'Hip Adductor Squeeze','Lie on back with knees bent, ball between knees. Squeeze ball and hold 5 seconds.','strengthening','3','15','1 time/day','4 weeks',NULL,NULL,'2026-07-04 05:30:09','2026-07-04 05:30:09',0,NULL,NULL);
/*!40000 ALTER TABLE `exercise_prescriptions` ENABLE KEYS */;
UNLOCK TABLES;

