INSERT INTO `sms_templates` VALUES (1,0,NULL,NULL,'patient_registration','Patient Registration','Hi {{patient_name}}, Welcome to {{clinic_name}}! Your registration is confirmed. Patient ID: {{patient_id}}. Call {{clinic_phone}} for More information.','Sent when a new patient registers',1,10,'2026-05-07 09:53:55','2026-05-07 09:53:55'),(2,0,NULL,NULL,'deposit_received','Deposit/Payment Received','Hi {{patient_name}}, We have received Rs.{{amount}} towards your treatment. Balance: Rs.{{balance}}. Thank you! - {{clinic_name}}','Sent when a payment/deposit is received',1,9,'2026-05-07 09:53:55','2026-05-07 09:53:55'),(3,0,NULL,NULL,'appointment_booked','Appointment Booked','Hi {{patient_name}}, Your appointment is confirmed for {{appointment_date}} at {{appointment_time}} with Dr.{{doctor_name}}. - {{clinic_name}}','Sent when an appointment is booked',1,8,'2026-05-07 09:53:55','2026-05-07 09:53:55'),(4,0,NULL,NULL,'appointment_reminder','Appointment Reminder','Reminder: You have an appointment tomorrow at {{appointment_time}} with Dr.{{doctor_name}}. Please arrive 10 min early. - {{clinic_name}}','Sent as appointment reminder',1,7,'2026-05-07 09:53:55','2026-05-07 09:53:55'),(5,0,NULL,NULL,'schedule_update','Schedule Update','Hi {{patient_name}}, Your appointment on {{old_date}} at {{old_time}} has been rescheduled to {{new_date}} at {{new_time}}. - {{clinic_name}}','Sent when appointment is rescheduled',1,6,'2026-05-07 09:53:55','2026-05-07 09:53:55'),(6,0,NULL,NULL,'due_reminder','Due Reminder','Hi {{patient_name}}, You have an outstanding balance of Rs.{{due_amount}}. Please clear your dues. - {{clinic_name}}','Sent for due payment reminder',1,5,'2026-05-07 09:53:55','2026-05-07 09:53:55'),(7,0,NULL,NULL,'payment_received','Payment Received','Payment Received! Rs.{{amount}} received for Invoice #{{invoice_no}}. Thank you. - {{clinic_name}}','Sent when payment is recorded',1,4,'2026-05-07 09:53:55','2026-05-07 09:53:55'),(8,0,NULL,NULL,'document_ready','Document Ready','Hi {{patient_name}}, Your {{document_type}} is ready for pickup. - {{clinic_name}}','Sent when documents are ready',1,3,'2026-05-07 09:53:55','2026-05-07 09:53:55');
